ALTER TABLE workshop.workshop_schedule
  ADD CONSTRAINT workshop_schedule_bays CHECK (bays BETWEEN 1 AND 50),
  ADD CONSTRAINT workshop_schedule_slot CHECK (slot_minutes IN (15, 30, 60));

ALTER TABLE workshop.workshop_hours
  ADD CONSTRAINT workshop_hours_weekday CHECK (weekday BETWEEN 0 AND 6),
  ADD CONSTRAINT workshop_hours_range CHECK (opens_minute >= 0 AND closes_minute <= 1440 AND opens_minute < closes_minute);

ALTER TABLE workshop.appointment
  ADD CONSTRAINT appointment_status_valid CHECK (status IN ('booked', 'checked_in', 'cancelled', 'no_show')),
  ADD CONSTRAINT appointment_time_range CHECK (ends_at > starts_at AND ends_at - starts_at <= interval '8 hours'),
  ADD CONSTRAINT appointment_checked_in_has_job CHECK ((status = 'checked_in') = (job_id IS NOT NULL)),
  ADD CONSTRAINT appointment_cancelled_has_reason CHECK (status <> 'cancelled' OR cancelled_reason IS NOT NULL);
